entries[98887] = { ["name"] = "Heilender Regen", ["text"] = "46% von Grundmana 40 Meter Reichweite\nWirken in 2 sek. 10 sek. Abklingzeit\nRuft heilende Regenschauer herbei, die über dem gewählten Gebiet herniedergehen. Stellt 10 Sek. lang alle 2 Sek. 756 Gesundheit von Verbündeten innerhalb des Gebiets wieder her. Befinden sich mehr als 6 Spieler in diesem Bereich, wird mit jedem weiteren die Wirksamkeit der Heilung verringert." }
entries[98888] = { ["name"] = "Machtwort: Barriere", ["text"] = "30% von Grundmana 40 Meter Reichweite\nSofort 3 min Abklingzeit\nBeschwört eine heilige Barriere im gewählten Gebiet, die jeglichen erlittenen Schaden aller befreundeten Ziele innerhalb ihres Bereiches um 25% verringert [ Glyphe 'Gebet der Heilung' : und ihre erhaltene Heilung um 10% erhöht ]. Innerhalb der Barriere wird das Wirken von Zaubern durch erlittenen Schaden nicht unterbrochen. Die Barriere hält 10 Sek. lang an." }
entries[98889] = { ["name"] = "Segenswort: Refugium", ["text"] = "44% von Grundmana 40 Meter Reichweite\nWirken in 0.5 sek. 40 sek. Abklingzeit\nWeiht den Boden mit einem heiligen Licht, durch welches alle Verbündeten in diesem Bereich alle 2 Sek. um 357 geheilt werden. Hält 18 Sek. lang an. Es kann jeweils nur ein Refugium gleichzeitig aktiv sein. Befinden sich mehr als 6 Spieler in diesem Bereich, wird mit jedem weiteren die Wirksamkeit der Heilung verringert." }
