entries[99660] = { ["name"] = "Ernter des Hexenjägers", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nEchtgold (8), Schweres primitives Leder (6), Gehärteter Elementiumbarren (4), Chaoskugel (5)\nErnter des Hexenjägers\nWird beim Anlegen gebunden\nZweihändig Stangenwaffe\n1,614 - 2,999 Schaden Tempo 3.50\n(659.00 Schaden pro Sekunde)\n+361 Beweglichkeit\n+541 Ausdauer\nErhöht Eure Meisterschaftswertung um + 241.\nHaltbarkeit 120 / 120\n85\nAnlegen: Erhöht die kritische Trefferwertung um 241." }
